// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    address deployer;

    function setUp() public {
        deployer = address(this);
        c = new MultiplicatorX4();
    }

    function testFuzz_property(address target, uint256 value) public {
        value = bound(value, 0, 1 ether);

        Reverter rev = new Reverter();
        Callee ok = new Callee();

        address chosen = (uint160(target) & 1 == 0) ? address(rev) : address(ok);

        vm.deal(deployer, value + 1 ether);

        vm.prank(deployer);

        bool okCall;
        try c.Command{value: value}(chosen, "\x00") {
            okCall = true;
        } catch {
            okCall = false;
        }

        assertTrue(okCall);
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}

contract Callee {
    event Called(address sender, uint256 value, bytes data);
    fallback() external payable {
        emit Called(msg.sender, msg.value, msg.data);
    }
    receive() external payable {
        emit Called(msg.sender, msg.value, "\x01");
    }
}
